use crate::common::transform::Transformation;

// Transformation arrays named by bitmask:
// Bit 0 = Identity, Bit 1 = Rotate90, Bit 2 = Rotate180, Bit 3 = Rotate270
// Bit 4 = ReflectHorizontal, Bit 5 = ReflectVertical
// Bit 6 = ReflectDiagonalMain, Bit 7 = ReflectDiagonalAnti
// Example: TRANS_0xFF = all 8 transformations (full D8 symmetry)
//          TRANS_0x0F = all 4 rotations (C4 rotational symmetry)
//          TRANS_0x01 = Identity only (no symmetry)

